650: \begin{proposition}\label{factorization}
651: 	For any $\lambda\in \mathfrak{z}^*\setminus \{0\}$ and $\nu\in S(\fv^*)$, the X-ray transform $I_{\nu, \lambda}: L^1(G)\to L^1(G_\lambda)$ is well-defined, bounded and factors in the following way:
652: 	\[ 
653: 	\begin{tikzcd}
654: 		L^1(G) \arrow[d, "P_{\lambda}" left=1]  \arrow[r, "{I}_{\nu, \lambda}"]  &L^1(G_\lambda)\\
655: 		L^1(G_{\lambda}) \arrow[ur, "\widetilde{I}_{\nu, \lambda}" below=10, pos=0.75]
656: 	\end{tikzcd}
657: 	\]
658: 	where the maps which we call \textit{central periodization} and the \textit{holonomy transform} are given by 
659: 	\begin{align*}
660: 		P_{\lambda}f(x, u)=\sum_{k\in\mathbb{Z}}f(x, u+\pi k |\lambda|^{-2}\hat{\lambda}), 
661: 		\quad \quad
662: 		\widetilde{I}_{\nu, \lambda}g(x, u)=\int_0^{2\pi |\lambda|^{-1}}g\left( (x, u)\gamma_{\nu, \lambda}(s)\right)ds
663: 	\end{align*}
664: 	for $f\in L^1(G)$ and $g\in L^1(G_\lambda)$.
665: \end{proposition}

1175: \begin{Proposition}\label{vertical-variation}
1176: Let $\gamma(t)=(x(t), B(t))$, $a\le t\le b$, be a curve on $\mathcal{P}$ which projects to $\tilde x(t)=(x(t), \dot x(t)/|\dot x(t)|)$. Let $\gamma_\epsilon(t)$ be a variation of $\gamma(t)$ fixing the endpoints such that the variation vector field $(\partial/\partial \epsilon)|_{\epsilon=0}\gamma_\epsilon(t)$ is vertical with respect to the fiberation $\mathcal{P}\to \Sigma$. Then, we~have
1177: \[
1178: \frac{\mathrm{d}}{\mathrm{d} \epsilon}\Big|_{\epsilon=0}
1179: \int _a^b \frac{G^{\mathrm{F}}(\dot \gamma_\epsilon(t), \dot \gamma_\epsilon(t))}{G^{\mathrm{F}}(K, \dot \gamma_\epsilon(t))}\,{\rm d}t=0.
1180: \]
1181: \end{Proposition}

251: \begin{lemma}[Polarization lemma]\label{lemma3.2}
252: Let $T$ be a symmetric $(0,2)$-tensor (at a point) such that $T(\ell,\ell)=0$ for every future-null vector (at that point). Then $T$ is proportional to $g$.
253: \end{lemma}

389: \begin{Theorem} \label{thm:Calphamapping}
390: Let $(M,g)$ be convex, non-trapping, and let $\phi\in C^\infty(SM)$. Suppose $f \in \A^E_{\phg}(SM)$ for some $C^\infty$-index set $E$ with
391: $s = \inf(E)>-1$. Then $I^\phi f \in \A^F_{\phg,\alpha}(\del_+ SM)$, where $F$ is a $C^\infty_\alpha$-index set contained in
392: (and possibly equal to) $\{ (2z+1,\ell), \ (z,\ell)\in E \}$.
407: \end{Theorem}

103: \begin{Theorem}\label{chain-projection}
104: Let $(\Sigma, [g])$ be a conformal $3$-manifold and $M$ the twistor CR manifold over $\Sigma$. Then, the following hold:
105: \begin{itemize}\itemsep=0pt
106: \item[$(1)$] Any chain and any null chain on $M$ project to a constant curve or a conformal geodesic on $\Sigma$.
107: \item[$(2)$] For any conformal geodesic $x(t)$, $a\le t\le b$, on $\Sigma$ and $[\zeta_0]\in M_{x(a)}$, there exists a unique chain $($resp.\ a null chain$)$ through $[\zeta_0]$ which projects to $x(t)$ when $g(\eta_0, \dot x(a))\neq0$ $($resp.\ $g(\eta_0, \dot x(a))=0)$, where $\eta_0:= {\rm i}\zeta_0\times \ol{\zeta_0}$.
108: \end{itemize}
109: \end{Theorem}
